def strategy(history, rng):
    n = len(history)
    if n == 0:
        return 'C'
    if n == 99:
        return 'D'

    me = [h[0] for h in history]
    op = [h[1] for h in history]
    op_c = op.count('C')
    op_d = n - op_c
    last_me = me[-1]
    last_op = op[-1]

    if op_c == 0:
        return 'D'
    if op_d == 0:
        return 'C'

    failed = 0
    for i in range(n - 1):
        if me[i] == 'C' and op[i+1] == 'D':
            failed += 1

    if last_op == 'D':
        if failed >= 3:
            return 'D'

        run = 0
        for i in range(n - 1, -1, -1):
            if op[i] == 'D':
                run += 1
            else:
                break

        if run == 1:
            if last_me == 'D':
                return 'C'
            if op_c * 2 >= n:
                return 'C'
            return 'D'

        if run >= 2:
            if run >= 4 and op_c > 0 and 'C' not in me[-3:] and 'C' in op[-10:]:
                return 'C'
            return 'D'

    return 'C'
